insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',1,'Língua Portuguesa',null,'O texto acima, cujo tema central é o plástico, está organizado estruturalmente em três blocos: o primeiro bloco vai do parágrafo 1 ao 4 (e não tem subtítulo próprio); o segundo bloco vai do parágrafo 5 ao 9 (sob o subtítulo A ilha transparente); e o terceiro bloco vai do parágrafo 10 ao 17 (sob o subtítulo A bactéria mutante). A alternativa que melhor captura, respectivamente, o subtema específico de cada bloco é:','{"A": "impacto do microplástico sobre a gestação / efeitos nocivos do plástico sobre a saúde humana / importância da conscientização do consumidor;", "B": "quantidade de microplástico circulante / impacto do plástico sobre o meio ambiente / soluções tecnológicas para combater os problemas causados pelo plástico;", "C": "relação entre o capitalismo e o consumo de plástico / legislações e acordos multilaterais de proteção ambiental / importância da conscientização do consumidor;", "D": "impacto do microplástico sobre a gestação / impacto do plástico sobre o meio ambiente / descobertas científicas fortuitas;", "E": "relação entre ingestão de plástico e saúde / existência de ameaças invisíveis / descobertas científicas fortuitas."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',2,'Língua Portuguesa',null,'No texto O futuro do plástico, o segundo bloco estrutural (A ilha transparente, parágrafos 5 a 9) pode ser internamente dividido em três partes menores: primeira parte (parágrafo 5); segunda parte (parágrafos 6 a 8); e terceira parte (parágrafo 9). O fator que individualiza cada uma dessas partes é seu modo de organização discursiva predominante. Os modos de organização discursiva predominantes em cada uma dessas três partes são, respectivamente:','{"A": "narração, narração e descrição;", "B": "exposição, narração e injunção;", "C": "descrição, narração e argumentação;", "D": "narração, descrição e exposição;", "E": "descrição, descrição e exposição."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',3,'Língua Portuguesa',null,'“E a enzima não só decompõe o plástico, ela o refaz: repolimeriza as moléculas do material, montando novamente as cadeias de átomos que formam o PET (e o tornam tão flexível e resistente).” (15º parágrafo) A informação expressa no fragmento acima já havia sido antecipada – com menor grau de detalhamento – em uma passagem anterior do texto. A alternativa que contém essa passagem é:','{"A": "“Um grupo de pesquisadores estava testando amostras do solo perto de uma usina de reciclagem de garrafas PET na cidade de Sakai, no Japão.” (12º parágrafo);", "B": "“O segredo dessa bactéria está numa enzima que ela produz: a PETase, que decompõe esse tipo de plástico.” (13º parágrafo);", "C": "“Nos anos seguintes, outras pesquisas descobriram dezenas de PETases, fabricadas por vários micro- organismos.” (13º parágrafo);", "D": "“Cientistas da Universidade do Texas criaram uma versão alterada da enzima” (14º parágrafo);", "E": "“Um a sete dias depois, dependendo da temperatura ambiente, você tem plástico novo.” (14º parágrafo)."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',4,'Língua Portuguesa',null,'Em função do seu potencial didático, a linguagem figurada costuma ser amplamente utilizada em reportagens sobre conteúdos científicos, cuja compreensão nem sempre é trivial para o leitor leigo. Dentre as passagens abaixo, a única em que a palavra sublinhada NÃO apresenta sentido figurado é:','{"A": "“Eles analisaram as placentas de 17 gestantes.” (1º parágrafo);", "B": "“E, ao chegar a este mundo, somos bombardeados por ele.” (2º parágrafo);", "C": "“e descobriram que, nelas, ‘chovem’ mais de 1.000 toneladas de microplásticos por ano, o equivalente a 120 milhões de garrafas PET.” (2º parágrafo);", "D": "“Ou seja: não estamos apenas sendo soterrados pelo plástico.” (4º parágrafo);", "E": "“Eles encontraram uma bactéria capaz de ‘comer’ esse material, transformando-o em energia para sobreviver.” (12º parágrafo)."}'::jsonb,'A',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',5,'Língua Portuguesa',null,'Todas as alternativas abaixo apresentam passagens retiradas de O futuro do plástico nas quais foi empregado o sinal gráfico das aspas. A alternativa em que a função desse sinal está INCORRETAMENTE identificada é:','{"A": "“Eles analisaram as placentas de 17 gestantes, e todas continham quantidades ‘muito abundantes’ de microplásticos.” (1º parágrafo) – chamar atenção para um uso redundante;", "B": "“e descobriram que, nelas, ‘chovem’ mais de 1.000 toneladas de microplásticos por ano” (2º parágrafo) – sinalizar uso conotativo;", "C": "“Eles encontraram uma bactéria capaz de ‘comer’ esse material, transformando-o em energia para sobreviver.” (12º parágrafo) – indicar imprecisão terminológica;", "D": "“e você precisa adicionar uma porcentagem cada vez maior de material ‘virgem’, ou seja, novo, para fazer as garrafas”. (16º parágrafo) – sinalizar uso conotativo;", "E": "“‘Agora dá para começar a enxergar uma verdadeira economia circular em torno do plástico’, disse o químico Hal Alper” (17º parágrafo) – marcar discurso direto."}'::jsonb,'A',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',6,'Língua Portuguesa',null,'“e descobriram que, nelas, ‘chovem’ mais de 1.000 toneladas de microplásticos por ano, o equivalente a 120 milhões de garrafas PET.” (2º parágrafo) “e concluiu que cada adulto ingere em média 20 gramas de microplásticos, o equivalente a uma pecinha de Lego, por mês” (3º parágrafo) As duas passagens acima ilustram o emprego de uma mesma estratégia discursiva, bastante comum em textos que buscam gerar impacto emocional. Essa estratégia consiste no recurso a:','{"A": "um raciocínio dialético, a fim de se obter uma síntese final;", "B": "uma referência histórica, a fim de tornar o argumento mais concreto para o leitor;", "C": "uma comparação, a fim de transpor uma determinada medida para a escala humana;", "D": "uma frase em ordem direta, a fim de tornar o texto mais claro;", "E": "sentenças ambíguas, a fim de incrementar a expressividade textual. Tipo 1 ̶ Branca – Página 5"}'::jsonb,'C',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',7,'Língua Portuguesa',null,'“Estamos expostos ao plástico antes mesmo de nascer. E, ao chegar a este mundo, somos bombardeados por ele. Literalmente.”(2º parágrafo) Nesta passagem, retirada do segundo parágrafo do texto O futuro do plástico, o advérbio “literalmente” não significa “de modo literal”. Em vez disso, ele é empregado para:','{"A": "enfatizar a urgência do enfrentamento aos impactos ambientais do plástico;", "B": "suavizar uma expressão potencialmente violenta;", "C": "restringir o conjunto de referentes abarcados pela frase anterior;", "D": "indicar que a afirmação anterior não é exagerada;", "E": "marcar o reconhecimento de que o problema do plástico se tornou irreversível."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',8,'Língua Portuguesa',null,'Embora pertença à modalidade escrita e tenha natureza pública, o texto O futuro do plástico apresenta algumas marcas de informalidade. A alternativa em que uma dessas marcas está corretamente identificada e exemplificada é:','{"A": "emprego de ordem inversa, como se vê em “Em setembro, um estudo publicado por cientistas chineses detectou, pela primeira vez, a presença de microplásticos (partículas com menos de 5 milímetros) na placenta humana.” (1º parágrafo);", "B": "emprego de oração adjetiva, como se vê em “E o cálculo não considera outros alimentos ou fontes, como os microplásticos presentes em cremes dentais ou liberados por panelas com o revestimento antiaderente danificado – que podem soltar mais de 9.000 pedacinhos a cada uso.” (4º parágrafo);", "C": "emprego de conjunção conclusiva inovadora, como se vê em “Só que a ilha não é bem como as pessoas imaginam” (7º parágrafo);", "D": "uso do ponto e vírgula não admitido pela norma padrão, como se vê em “Ele se chama Cryptococcus neoformans, e a ciência já o conhecia; mas essa sua nova habilidade, não. (11º parágrafo);", "E": "estrutura de sujeito indeterminado não reconhecida pela tradição gramatical, como se vê em “No método tradicional, isso não acontece: o plástico perde qualidade após cada reciclagem, e você precisa adicionar uma porcentagem cada vez maior de material ‘virgem’, ou seja, novo, para fazer as garrafas.” (16º parágrafo)."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',9,'Língua Portuguesa',null,'“No método tradicional, isso não acontece: o plástico perde qualidade após cada reciclagem” (16º parágrafo) As duas orações acima não estão ligadas por um conector (e sim pelo sinal de dois-pontos). Apesar disso, é correto afirmar que a segunda oração contrai, em relação à primeira, valor semântico de:','{"A": "conclusão;", "B": "condição;", "C": "causa;", "D": "conformidade;", "E": "adversidade."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',10,'Língua Portuguesa',null,'“Só que a ilha não é bem como as pessoas imaginam, com uma gigantesca maçaroca flutuante. Em sua maior parte, ela é invisível a olho nu. Isso porque o lixo vai se fragmentando – e 80% dele já está na forma de microplásticos. Eles são muito pequenos, e ficam espalhados por uma área gigantesca. Por isso, a ilha é difícil de ver – seja de barco ou por imagens de satélite.” (7º e 8º parágrafos) A proposta de reescritura dos parágrafos acima em que todas as relações lógico-semânticas presentes no texto original são preservadas é:','{"A": "A ilha, contudo, não é bem como as pessoas imaginam, com uma gigantesca maçaroca flutuante. Em sua maior parte, ela é invisível a olho nu; logo, o lixo vai se fragmentando – e 80% dele já está na forma de microplásticos. Estes são muito pequenos, e ficam espalhados por uma área gigantesca. Por isso, a ilha é difícil de ver – seja de barco ou por imagens de satélite;", "B": "Só que a ilha não é bem como as pessoas imaginam, com uma gigantesca maçaroca flutuante. Como o lixo se fragmenta gradualmente – e 80% dele já está na forma de microplásticos –, o resultado é uma ilha, na sua maior parte, invisível a olho nu. Tais microplásticos são, de fato, muito pequenos, e ficam espalhados por uma área gigantesca, razão pela qual a ilha é difícil de ver – seja de barco ou por imagens de satélite;", "C": "Só que a ilha não é bem como as pessoas imaginam, com uma gigantesca maçaroca flutuante. Ela é, em sua maior parte, invisível a olho nu. Isso porque o lixo vai se fragmentando – e 80% dele já está na forma de microplásticos; Eles são muito pequenos, não obstante ficarem espalhados por uma área gigantesca. Por isso, a ilha é difícil de ver – seja de barco ou por imagens de satélite.;", "D": "A ilha não é, entretanto, exatamente como as pessoas imaginam, com uma gigantesca maçaroca flutuante. Em sua maior parte, ela é invisível a olho nu. Isso à medida que o lixo vai se fragmentando – e 80% dele já está na forma de microplásticos. Eles são muito pequenos, e ficam espalhados por uma área gigantesca. Por isso, a ilha é difícil de ver – seja de barco ou por imagens de satélite;", "E": "Só que a ilha não é bem como as pessoas imaginam, com uma gigantesca maçaroca flutuante. Em virtude de ela ser, em sua maior parte, invisível a olho nu, seu lixo vai se fragmentando – e 80% dele já está na forma de microplásticos. Eles são muito pequenos, e ficam espalhados por uma área gigantesca. Por isso, a ilha é difícil de ver – seja de barco ou por imagens de satélite."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',11,'Matemática',null,'Juliana aplicou um valor 𝑥 em um investimento que rende mensalmente, com taxa de juros equivalente a 300% em 10 anos. Após 5 anos, o valor que Juliana tem neste investimento é de R$ 36.000,00. O valor 𝑥 aplicado é de:','{"A": "R$ 12.000,00;", "B": "R$ 16.000,00;", "C": "R$ 18.000,00;", "D": "R$ 20.000,00;", "E": "R$ 24.000,00. Tipo 1 ̶ Branca – Página 6"}'::jsonb,'C',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',12,'Matemática',null,'Certa pizzaria vende uma pizza média, que é circular com raio de 10 cm, por R$ 20,00. Supondo que o preço da pizza é proporcional à sua área, o preço da pizza grande, que também é circular e tem raio de 15 cm, é de:','{"A": "R$ 30,00;", "B": "R$ 35,00;", "C": "R$ 40,00;", "D": "R$ 42,00;", "E": "R$ 45,00."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',13,'Matemática',null,'Armando comprou um equipamento pagando R$ 5.000,00 no ato da compra e mais R$ 6.000,00 um mês depois, quitando a compra. A taxa de juros mensal que o vendedor aplicou foi de 20%. O valor do produto à vista era de:','{"A": "R$ 6.000,00;", "B": "R$ 7.000,00;", "C": "R$ 8.000,00;", "D": "R$ 9.000,00;", "E": "R$ 10.000,00."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',14,'Matemática',null,'Sabe-se que 10 máquinas iguais operando por 10 minutos produzem 20 litros de sorvete a mais do que 8 máquinas operando por 8 minutos. São produzidos por 3 máquinas operando por 12 minutos:','{"A": "10 litros de sorvete;", "B": "16 litros de sorvete;", "C": "20 litros de sorvete;", "D": "30 litros de sorvete;", "E": "36 litros de sorvete."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',15,'Matemática',null,'Luiza tinha uma conta para pagar de R$ 1.000,00, que vencia no dia 25 de novembro de 2022. Ela só pagou no dia 5 de dezembro de 2022. Se os juros de mora (juros simples) são de 15% ao mês, Luiza pagou:','{"A": "R$ 1.036,00;", "B": "R$ 1.040,00;", "C": "R$ 1.050,00;", "D": "R$ 1.060,00;", "E": "R$ 1.064,00."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',16,'Matemática',null,'A loja de José vende o produto X por R$ 170,00 cada unidade. O produto é isento de imposto ICMS. O governo decidiu que o ICMS de 15% deverá incidir sobre esse produto. Para que a receita da loja com a venda de uma unidade de X permaneça a mesma, o preço deve passar a ser de:','{"A": "R$ 180,00;", "B": "R$ 185,00;", "C": "R$ 190,00;", "D": "R$ 195,00;", "E": "R$ 200,00."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',17,'Matemática',null,'Otávio financiou a compra de uma TV que custa R$ 3.000,00 à vista para pagar em uma única parcela um mês após a compra, com taxa de juros mensal de 5%. Leonel financiou a compra da mesma TV, que custa R$ 3.000,00 à vista, para pagar em uma única parcela um mês após a compra, com taxa de juros mensal j. Sabendo-se que Otávio pagou R$ 60,00 a mais do que Leonel, a taxa de juros j é de:','{"A": "1%;", "B": "1,5%;", "C": "2%;", "D": "2,5%;", "E": "3%."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',18,'Matemática',null,'Ana fez um empréstimo com uma taxa de juros efetiva de 50% ao ano. O sistema de amortização é a tabela PRICE, com 24 parcelas mensais iguais a P. Se em vez de 24 parcelas, o prazo fosse de 48 parcelas iguais, pela tabela PRICE e com a mesma taxa de juros, o valor de cada parcela seria de:','{"A": "1 2 𝑃 ;", "B": "3 5 𝑃 ;", "C": "2 3 𝑃 ;", "D": "3 4 𝑃 ;", "E": "4 5 𝑃 ."}'::jsonb,'X',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; questão ANULADA pela banca; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',19,'Matemática',null,'Celina fez um empréstimo de R$ 50.000,00 com uma taxa de juros de 4% ao mês. O sistema de amortização é o SAC, sistema de amortizações constantes, com 10 parcelas mensais. O valor da primeira parcela, paga um mês após o recebimento do empréstimo, é de:','{"A": "R$ 6.750,00;", "B": "R$ 7.000,00;", "C": "R$ 7.800,00;", "D": "R$ 8.000,00;", "E": "R$ 8.800,00. Tipo 1 ̶ Branca – Página 7"}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',20,'Matemática',null,'Certo imóvel está avaliado em R$ 1.000.000,00. O valor do aluguel mensal do imóvel, pago vencido, que é compatível com a taxa corrente de juros de 0,5% ao mês é de:','{"A": "R$ 4.000,00;", "B": "R$ 4.200,00;", "C": "R$ 4.500,00;", "D": "R$ 5.000,00;", "E": "R$ 5.200,00."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',21,'Direito Administrativo',null,'Caio, servidor público, praticou ato ilícito doloso, no exercício de sua função, gerando prejuízo ao erário. Posteriormente, Caio foi absolvido na esfera penal, em ação penal que versou sobre o mesmo ato ilícito, por insuficiência de provas. No caso em tela, em matéria de responsabilidade civil para ressarcimento ao erário e responsabilidade administrativa disciplinar, de acordo com a atual jurisprudência das Cortes Superiores e a legislação em vigor, é correto afirmar que:','{"A": "Caio não poderá ser processado civilmente, podendo, entretanto, sofrer punição administrativa;", "B": "Caio poderá ser processado civilmente, não podendo responder administrativamente;", "C": "Caio poderá ser processado civil e administrativamente;", "D": "a ação regressiva do Estado contra Caio deve obedecer ao prazo prescricional equivalente a oito anos nos termos do Art. 205 do Código Civil;", "E": "na ocorrência de absolvição no âmbito criminal, por insuficiência de provas, não é viável buscar a reparação dos danos junto aos sucessores do agente público."}'::jsonb,'C',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',22,'Direito Administrativo',null,'O Município X realizou licitação visando à contratação de fornecimento de materiais necessários às atividades corriqueiras da Administração. Não houve interessados. De acordo com a Lei nº 14.133/2021, é correto afirmar que:','{"A": "a hipótese do enunciado configura licitação fracassada, caso em que é viável a dispensa de licitação, com a contratação direta pela Administração;", "B": "na hipótese formulada, a Administração deverá publicar, a quem interessar, no prazo de quinze dias úteis, nova oportunidade para a apresentação de documentação, em segunda oportunidade;", "C": "a hipótese do enunciado configura licitação deserta, sendo dispensável a licitação, desde que, dentre outros requisitos, sejam mantidas as condições preestabelecidas;", "D": "frustrada a licitação, não são mais exigíveis as mesmas condições prévias, podendo o contrato ser realizado diretamente, com dispensa de licitação, prevendo-se novas e diversas cláusulas;", "E": "a licitação descrita no enunciado afigura-se fracassada, devendo, de imediato, se elaborar novo edital e aguardar eventuais habilitações."}'::jsonb,'C',true,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',23,'Direito Administrativo',null,'O Município X enfrentou, diante de fortes chuvas, casos graves de alagamentos e deslizamentos, tendo sido decretada calamidade pública. Com base na Lei nº 14.133/2021 e na jurisprudência atuais, é correto afirmar que:','{"A": "o caso descrito no enunciado não se amolda à hipótese de dispensa, mas de inexigibilidade de licitação;", "B": "a licitação, no caso descrito no enunciado, é dispensável, podendo a contratação eventualmente realizada ser renovada por até três meses;", "C": "a licitação, no caso descrito no enunciado, é inexigível, uma vez que os fatos foram causados por forças da natureza, imprevisíveis para a Administração;", "D": "o enunciado revela hipótese de dispensa de licitação, quando caracterizada urgência de atendimento de situação que possa, dentre outras consequências, ocasionar prejuízo;", "E": "o enunciado revela hipótese de licitação dispensável, sendo certo que, nas hipóteses de realização de obras e serviços, pode haver prorrogação dos respectivos contratos, desde que devidamente justificada pela Administração e no prazo máximo de cinco anos."}'::jsonb,'D',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',24,'Direito Administrativo',null,'Caio, servidor estável, começou a passar por um difícil período, pois está sofrendo limitação em sua capacidade mental, que o deixou inapto para o exercício das funções do seu cargo. Após diversos exames médicos, não foi constatada invalidez permanente. Com base na Constituição da República de 1988, é correto afirmar que:','{"A": "Caio poderá ser reintegrado à Administração Pública, aproveitado em setor diverso de suas funções iniciais;", "B": "o aproveitamento de Caio será viável, podendo requerer novos exames após um ano, visando a aferir eventual possibilidade de retorno ao cargo inicial;", "C": "a reversão, como forma de provimento derivado, será a hipótese que se amolda aos fatos narrados no enunciado, devendo Caio retornar às atividades junto à Administração;", "D": "Caio poderá ser readaptado para qualquer outro cargo que escolher na Administração Pública, ainda que de escolaridade diversa de seu cargo de origem, uma vez que não foi constatada invalidez;", "E": "Caio poderá ser readaptado para o exercício de cargo cujas atribuições e responsabilidades sejam compatíveis com a limitação que sofreu, enquanto permanecer nessa condição, desde que possua a habilitação e o nível de escolaridade exigidos para o cargo de destino. Tipo 1 ̶ Branca – Página 8"}'::jsonb,'E',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',25,'Direito Administrativo',null,'No ano de 2020, sob o regime jurídico da Lei nº 8.666/1993, foi celebrado contrato entre pessoa jurídica de direito privado e o Município X sem a realização de procedimento licitatório exigido em lei. O negócio jurídico foi invalidado. Considerando-se a legislação em vigor e a jurisprudência atualizada, é correto afirmar que:','{"A": "a declaração de nulidade do contrato não opera retroativamente;", "B": "a ausência de procedimento licitatório devido demonstra a má-fé dos agentes responsáveis pela condução da contratação, pela Administração Pública, sendo sua consequência lógica, a nulidade do contrato e a indenização do contratado;", "C": "nos casos de ter o contratado concorrido para a nulidade ou demonstrada sua má-fé, não há o dever de indenizar por parte da Administração Pública;", "D": "a pessoa jurídica contratada deverá ser indenizada, ainda que tenha concorrido para a nulidade, vedado o enriquecimento ilícito da Administração Pública;", "E": "os serviços prestados à Administração Pública em decorrência de contrato nulo não são indenizáveis, ainda que haja boa-fé do contratado."}'::jsonb,'C',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',26,'Direito Administrativo',null,'Tício inscreveu-se em concurso público para o provimento de cargo efetivo junto ao Município, tendo sido abertas vinte vagas. Com a publicação do resultado, constatou que foi classificado em vigésimo quinto lugar. A Administração Pública Municipal vem nomeando aos poucos os candidatos aprovados, restando pouco tempo para o encerramento do prazo do concurso. De acordo com a legislação em vigor, é correto afirmar que, em regra:','{"A": "a Administração Municipal é obrigada a nomear Tício, uma vez que, classificado no concurso público, tem direito líquido e certo a ser cumprido;", "B": "classificado em concurso público, Tício tem direito líquido e certo à nomeação, mas necessitará ajuizar demanda judicial para tanto, uma vez que foi classificado além das vagas do edital;", "C": "Tício não tem direito líquido e certo à nomeação na hipótese formulada, uma vez que foi classificado em posição além das vagas inicialmente oferecidas pelo edital;", "D": "há direito líquido e certo de Tício ser nomeado na hipótese formulada, nada impedindo que, até a finalização dos trâmites, para suprir a necessidade do serviço, a Administração Pública contrate servidores temporários para o mesmo cargo;", "E": "a criação das vagas em lei e a realização de concurso público vinculam a Administração, que deve nomear todos os candidatos classificados."}'::jsonb,'C',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',27,'Direito Administrativo',null,'Tício foi recentemente aprovado em concurso público para cadastro de reserva. Aguardando nomeação, teve ciência da contratação temporária de Caio para o mesmo cargo. Com base na legislação em vigor e na jurisprudência pátria, é correto afirmar que:','{"A": "Tício é titular de direito público subjetivo à nomeação, não podendo ser preterido em qualquer hipótese;", "B": "Tício, aprovado para cadastro de reserva, tem inicialmente mera expectativa de direito, exigindo-se ato imotivado e arbitrário da Administração Pública para convolá-la em direito subjetivo;", "C": "a contratação temporária de Caio, mesmo não se destinando ao suprimento de vacância existente em razão do afastamento temporário do titular do cargo efetivo, não enseja qualquer direito a Tício, em qualquer caso, uma vez que foi aprovado para cadastro de reserva;", "D": "a contratação temporária, ainda que visando a atender necessidade temporária excepcional de interesse público, demonstra a existência de cargo público vago, passível de provimento;", "E": "Tício, aprovado para cadastro de reserva, tem direito público subjetivo à nomeação, em qualquer caso, devendo ser imediatamente nomeado."}'::jsonb,'B',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',28,'Direito Administrativo',null,'Caio, agente público municipal, divulgou, sem autorização, informações pessoais de terceiros, causando-lhes danos, motivo pelo qual os prejudicados pretendem ajuizar demandas buscando responsabilização. Considerando-se os dispositivos vigentes na Lei nº 12.527/2011 e no Decreto Rio nº 44.745/2018, é correto afirmar que:','{"A": "Caio não é passível de qualquer responsabilização, uma vez que a entidade pública à qual está vinculado responde exclusivamente pelos danos causados;", "B": "Caio deve ser responsabilizado diretamente, cabível a responsabilidade subsidiária do órgão ou entidade pública à qual está vinculado;", "C": "a entidade pública à qual Caio é vinculado responde diretamente pelos danos causados, sendo possível a apuração da responsabilidade funcional de Caio nos casos de dolo ou culpa, assegurado o direito de regresso;", "D": "a entidade pública à qual Caio é vinculado responde diretamente pelos danos causados, sendo possível a apuração da responsabilidade funcional de Caio somente nos casos de dolo, assegurado o direito de regresso;", "E": "a divulgação de informações pessoais de terceiros somente é possível diante do consentimento expresso da pessoa a que elas se referirem. Tipo 1 ̶ Branca – Página 9"}'::jsonb,'C',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',29,'Direito Administrativo',null,'Caio prestou concurso público para provimento de cargo junto à Administração Pública, tendo sido aprovado. Em razão de litígio judicial pendente sobre o concurso público, Caio somente foi nomeado e empossado muitos meses depois da aprovação, após decisão judicial em seu favor. Tempos depois, Caio ajuizou ação em face do ente federativo, postulando indenização em razão da demora em sua investidura. Com base na legislação em vigor e na jurisprudência pátria, é correto afirmar que:','{"A": "Caio deveria ter postulado indenização antes de se tornar servidor público;", "B": "Caio não faz jus à indenização, salvo na hipótese de demonstrada arbitrariedade flagrante da Administração Pública;", "C": "na hipótese descrita Caio não faz jus à indenização, uma vez que foi nomeado e empossado, sendo desnecessário se perquirir qualquer arbitrariedade da Administração Pública;", "D": "Caio faz jus à indenização em razão da demora em sua investidura, ainda que não constatada arbitrariedade da Administração Pública, pois seu direito à nomeação e posse era líquido e certo;", "E": "na hipótese descrita, constatada arbitrariedade flagrante da Administração Pública, Caio deverá buscar indenização diretamente em face do agente público responsável pela demora."}'::jsonb,'B',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',30,'Direito Administrativo',null,'Tício é motorista de ônibus pertencente à sociedade empresária concessionária prestadora de serviços de transporte municipal. Em determinado dia de trabalho, na condução do ônibus, avistou sua namorada em um carro à frente, aos beijos com outro homem. Movido por ciúmes, Tício jogou o ônibus na direção do carro, danificando-o e lesionando seus ocupantes. Considerando a legislação em vigor e atualizada jurisprudência, é correto afirmar que:','{"A": "os ocupantes do veículo somente podem buscar indenização em face do motorista, Tício, uma vez que não estavam na condição de usuários do serviço de transporte público coletivo no momento dos fatos;", "B": "há responsabilidade objetiva da sociedade empresária concessionária prestadora do serviço público de transporte municipal mesmo em relação aos danos causados a terceiros não usuários;", "C": "há responsabilidade subjetiva da sociedade empresária concessionária prestadora do serviço público de transporte municipal mesmo em relação aos danos causados a terceiros não usuários;", "D": "a sociedade empresária concessionária prestadora do serviço público de transporte municipal não responderá pelos danos causados a terceiros, se for comprovado que não houve culpa de seu agente;", "E": "a sociedade empresária concessionária prestadora do serviço público de transporte municipal não responderá pelos danos causados a terceiros, ainda que não usuários, se for comprovado que seu agente agiu com arbitrariedade e ilegalidade."}'::jsonb,'B',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',31,'Direito Constitucional',null,'O chefe do Poder Executivo do Município Alfa tinha grande admiração profissional por Maria, servidora ocupante de cargo de provimento efetivo no Município Alfa; Joana, servidora aposentada do Município Alfa; e Ana, que não ocupava cargo público. Ao se inteirar de vacâncias na estrutura administrativa, tomou conhecimento de que poderia realizar nomeações para um cargo em comissão (CC) e para uma função de confiança (FC). Ao consultar sua assessoria, foi-lhe corretamente informado que, à luz da sistemática constitucional:','{"A": "todas podem ser nomeadas para CC e FC;", "B": "Maria pode ser nomeada para CC ou FC, enquanto Joana e Ana somente podem ser nomeadas para CC;", "C": "Maria somente pode ser nomeada para FC, enquanto Joana e Ana podem ser nomeadas para CC ou FC;", "D": "Maria e Joana podem ser nomeadas para CC ou FC, enquanto Ana somente pode ser nomeada para CC;", "E": "Maria e Ana somente podem ser nomeadas para CC, enquanto Joana somente pode ser nomeada para FC."}'::jsonb,'B',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',32,'Direito Constitucional',null,'Bruna, servidora ocupante de cargo de provimento efetivo no Município Beta, por ter preenchido os requisitos exigidos pelo respectivo regime próprio de previdência social, requereu o deferimento de sua aposentadoria voluntária. Ato contínuo, questionou sua amiga Ana a respeito do procedimento a ser adotado para que o seu requerimento fosse deferido. Ana respondeu, corretamente, que:','{"A": "se trata de ato complexo, a ser sucessivamente apreciado pelo órgão competente de Beta e pelo Tribunal de Contas, somente começando a produzir efeitos após as manifestações favoráveis de ambos;", "B": "será apreciado pelo órgão competente de Beta, sendo cabível a interposição de recurso, direcionado ao Tribunal de Contas, em que se argumente com a ilegalidade do ato, desde que não aperfeiçoado o prazo decadencial de cinco anos;", "C": "se trata de ato composto, em que a integração de eficácia do ato de aposentadoria principia pelo órgão competente de Beta e se aperfeiçoa de maneira escalonada e sucessiva, somente começando a produzir efeitos após o exaurimento do prazo recursal no âmbito do Tribunal de Contas, que se manifesta sempre por último;", "D": "se trata de ato complexo, mas o ato de concessão inicial da aposentadoria produz efeitos imediatos e é encaminhado ao Tribunal de Contas para fins de registro, sendo avaliada a sua legalidade, observando-se sempre o contraditório e a ampla defesa quando da decisão possa resultar anulação ou revogação do ato que beneficia Bruna;", "E": "será apreciado pelo órgão competente de Beta, sendo o ato de concessão inicial da aposentadoria encaminhado ao Tribunal de Contas para fins de registro, não sendo necessário se observar o contraditório e a ampla defesa ainda que da decisão possa resultar anulação ou revogação do ato que beneficia Bruna, salvo a situação reconhecida como de demora excessiva. Tipo 1 ̶ Branca – Página 10"}'::jsonb,'E',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',33,'Direito Constitucional',null,'A partir de projeto de lei apresentado pelo prefeito do Município Beta, veio a ser publicada a Lei nº XX, que disciplinou: (1) a forma de prestação do serviço local de gás canalizado; (2) as regras mínimas de segurança do trabalho no exercício dessa atividade; e (3) as normas que regeriam as obrigações assumidas pelos usuários do serviço. Ao tomar conhecimento dos termos da Lei nº XX, a associação das sociedades empresárias que exploravam essa atividade solicitou que o seu advogado analisasse a compatibilidade formal das suas normas com a ordem constitucional. O advogado respondeu, corretamente, em relação às normas 1, 2 e 3, que:','{"A": "somente 1 é constitucional;", "B": "somente 1 e 2 são constitucionais;", "C": "somente 1 e 3 são constitucionais;", "D": "somente 2 e 3 são constitucionais;", "E": "todas são inconstitucionais."}'::jsonb,'E',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',34,'Direito Constitucional',null,'João, estudante de direito, questionou o seu professor se a organização do Poder Judiciário permitia que uma sentença proferida por juiz federal pudesse ser objeto de recurso a ser julgado diretamente pelo Supremo Tribunal Federal (STF). O professor respondeu, corretamente, que a sentença:','{"A": "que julga crime político pode ser objeto de recurso ordinário a ser julgado pelo STF;", "B": "que julga causa relativa a direitos humanos pode ser objeto de recurso de apelação a ser julgado pelo STF;", "C": "que julga qualquer causa e que contraria a Constituição da República de 1988 pode ser objeto de recurso extraordinário a ser julgado pelo STF;", "D": "que apreciar causa em que for parte organismo internacional, de um lado, e, do outro, Município, pode ser objeto de recurso ordinário a ser julgado pelo STF;", "E": "somente pode ser impugnada perante o Tribunal Regional Federal competente e, uma vez exaurida a instância ordinária, pode ser manejado o recurso cabível perante o STF."}'::jsonb,'A',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',35,'Direito Constitucional',null,'Constatou-se que uma grande quantidade de pessoas vinha se estabelecendo no Município Alfa para exercer a atividade profissional de encadernador, o que atraía consumidores de diversas partes do país em razão da excelência do serviço prestado, especialmente em relação à restauração de livros raros. Por outro lado, também se observou que diversos oportunistas, sem qualquer conhecimento do ofício, passaram a atuar no Município, colocando em risco a credibilidade da totalidade dos encadernadores. Por tal razão, foi editada a Lei municipal nº XX, estabelecendo os requisitos mínimos para o exercício da atividade profissional de encadernador no território municipal, os quais se cingiam à comprovação de experiência na área. À luz da divisão constitucional de competências, é correto afirmar que a Lei municipal nº XX é:','{"A": "constitucional, pois compete aos Municípios legislar sobre matérias de interesse local;", "B": "constitucional, considerando a concepção de preeminência do interesse, própria do federalismo cooperativo;", "C": "inconstitucional, pois compete privativamente à União legislar sobre condicionantes para o exercício profissional;", "D": "inconstitucional, pois compete concorrentemente à União, aos Estados e ao Distrito Federal legislar sobre o exercício de atividade econômica;", "E": "inconstitucional, desde que a norma municipal tenha se limitado a suplementar as normas editadas pela União ou pelo Estado no qual Alfa está situado."}'::jsonb,'C',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',36,'Direito Constitucional',null,'Joana, Maria e Antônio travaram um debate a respeito de algumas características dos direitos sociais à luz da sistemática constitucional. Joana sustentava que, na maior parte das vezes, mas não sempre, assumiam contornos prestacionais. Maria defendia que direitos dessa natureza são sempre compreendidos na perspectiva do agregado social, não sendo possível perquirir a sua fruição, ou não, em uma perspectiva individualista. Antônio, por sua vez, defendia que as liberdades fundamentais e os direitos sociais devem ser compreendidos na perspectiva da indivisibilidade dos direitos fundamentais. Inês, ao analisar as afirmações apresentadas, concluiu, corretamente, que:','{"A": "todas estão certas;", "B": "somente as afirmações de Joana e Antônio estão certas, enquanto a de Maria está errada;", "C": "somente a afirmação de Maria está certa, enquanto as de Joana e Antônio estão erradas;", "D": "somente a afirmação de Joana está certa, enquanto as de Maria e Antônio estão erradas;", "E": "somente as afirmações de Maria e Antônio estão certas, enquanto a de Joana está errada. Tipo 1 ̶ Branca – Página 11"}'::jsonb,'B',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',37,'Direito Constitucional',null,'João, profissional vinculado a determinado conselho de fiscalização do exercício profissional, ao consultar um motor de busca na internet, ficou surpreso com a descoberta de que o seu nome figurava em uma lista de devedores da anuidade que deveria ser paga ao conselho, correspondente a um exercício financeiro de dez anos atrás. Receoso de que isso pudesse contribuir para a formação de uma imagem negativa junto aos seus clientes, embora se tratasse de fato isolado, correspondente a um ano em que estivera impossibilitado de trabalhar, por se encontrar doente, consultou um advogado a respeito da licitude dessa divulgação. O advogado respondeu, corretamente, que a referida divulgação é:','{"A": "ilícita, por configurar afronta ao direito à privacidade;", "B": "lícita, estando abrangida pela liberdade de informação;", "C": "ilícita, porque a divulgação de informações afetas ao conselho e a João exigia a autorização de ambos;", "D": "lícita, até o momento em que João apresentar uma posição contrária à divulgação, existindo o direito à sua exclusão;", "E": "ilícita, por ser potencialmente contrária ao direito social ao trabalho, podendo dificultar a captação de clientes por João."}'::jsonb,'B',true,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',38,'Direito Constitucional',null,'Em uma gincana jurídica, os grupos Alfa, Beta e Ômega foram instados a se manifestar sobre o conteúdo dos princípios fundamentais expressamente veiculados no Título I da Constituição da República de 1988. O grupo Alfa defendeu que a forma de Estado adotada foi mencionada no rol desses princípios. O grupo Beta observou que a forma de governo foi objeto de previsão específica. O grupo Ômega, por sua vez, defendeu que o sistema de governo foi expressamente contemplado. Ao final da gincana, o júri observou, corretamente, em relação às afirmações dos grupos, que:','{"A": "somente as afirmações dos grupos Alfa e Ômega estavam corretas;", "B": "somente as afirmações dos grupos Alfa e Beta estavam corretas;", "C": "somente a afirmação do grupo Ômega estava correta;", "D": "somente a afirmação do grupo Beta estava correta;", "E": "as afirmações de todos os grupos estavam corretas."}'::jsonb,'B',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',39,'Direito Constitucional',null,'Em razão do aumento dos casos de roubos em agências bancárias, o Estado Alfa editou a Lei nº XX, determinando a instalação de certos equipamentos de segurança nesses locais, de modo a evitar ou a minorar as consequências desses ilícitos, o que não importou em qualquer afronta à norma editada pela União. Por entender que as medidas preconizadas pela lei estadual eram excessivamente onerosas, uma instituição financeira consultou o seu advogado a respeito de sua compatibilidade formal com a Constituição da República de 1988. Foi corretamente respondido que a Lei nº XX é:','{"A": "inconstitucional, pois compete privativamente aos Municípios legislar sobre assuntos de interesse local;", "B": "inconstitucional, pois compete privativamente à União legislar sobre o Sistema Financeiro Nacional;", "C": "constitucional, pois o Estado tem competência concorrente com a União para legislar sobre a segurança alvitrada;", "D": "inconstitucional, ressalvada a existência de lei complementar delegando a competência legislativa da União aos Estados;", "E": "constitucional, pois os Estados têm competência legislativa comum com a União para legislar sobre estabelecimentos bancários."}'::jsonb,'C',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',40,'Direito Constitucional',null,'XX, vereador na Câmara Municipal do Rio de Janeiro, consultou sua assessoria a respeito da possibilidade de serem apresentados projetos de decreto legislativo, observados os balizamentos estabelecidos na Lei Orgânica do Município do Rio de Janeiro e os requisitos regimentais, que tenham por objeto: (1) propor ao Plenário a criação, a transformação e a extinção de cargos, empregos ou funções da Câmara Municipal; (2) responder aos requerimentos enviados à Mesa Diretora pelos vereadores; (3) aprovação dos nomes dos conselheiros do Tribunal de Contas do Município; e (4) convocação do prefeito para prestar informações sobre matérias de sua competência. A assessoria informou, corretamente, em relação aos possíveis objetos dos projetos de decreto legislativo, previstos em 1, 2, 3 e 4, que:','{"A": "todos podem ser objeto de decreto legislativo;", "B": "somente aqueles referidos em 1, 2 e 4 podem ser objeto de decreto legislativo;", "C": "somente aqueles referidos em 2 e 4 podem ser objeto de decreto legislativo;", "D": "somente aquele referido em 3 pode ser objeto de decreto legislativo;", "E": "somente aquele referido em 1 pode ser objeto de decreto legislativo. Tipo 1 ̶ Branca – Página 12 Objetiva P2 - Conhecimentos Específicos - Contabilidade Aplicada ao Setor Público, Contabilidade Geral, Finanças Públicas, Auditoria Governamental"}'::jsonb,'D',false,true,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',41,'Contabilidade Pública',null,'As entidades do setor público possuem características que as diferem das demais entidades. Uma dessas diferenças está nos objetivos da elaboração das demonstrações contábeis, que têm foco no fornecimento de informações úteis, tendo em vista o processo de prestação de contas e responsabilização. A elaboração de tais demonstrações de acordo com as normas definidas no MCASP é facultativa para:','{"A": "conselhos profissionais;", "B": "consórcios públicos;", "C": "empresas estatais dependentes;", "D": "fundações públicas;", "E": "fundos públicos."}'::jsonb,'A',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',42,'Contabilidade Pública',null,'No processo de implantação de procedimentos contábeis patrimoniais, um ente público municipal promoveu uma avaliação dos itens incluídos em seu ativo imobilizado há mais de cinco anos e que em geral não são negociados em um mercado ativo. O gestor patrimonial solicitou um relatório detalhado de tais ativos, a partir de uma base de mensuração a valores de entrada. Para atender a solicitação do gestor, o referido relatório pode ser apresentado considerando:','{"A": "custo de liberação;", "B": "custo de reposição;", "C": "preço líquido de venda;", "D": "preço presumido;", "E": "valor em uso."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',43,'Contabilidade Pública',null,'Uma entidade pública contratou uma consultoria para avaliar a aderência dos seus procedimentos contábeis no contexto da convergência às normas internacionais aplicadas ao setor público. Ao avaliar as demonstrações contábeis emitidas pela entidade, à luz da NBC TSP 11 - Apresentação das Demonstrações Contábeis, a consultoria verificou a inclusão de demonstrações e informações adicionais às exigidas na referida norma, a exemplo:','{"A": "da demonstração do resultado;", "B": "da demonstração dos fluxos de caixa;", "C": "de informação comparativa com o período anterior;", "D": "de notas explicativas acerca das políticas contábeis;", "E": "do balanço financeiro."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',44,'Contabilidade Pública',null,'Ao considerar a concepção de um modelo de gerenciamento de custos, nos termos da NBC TSP34 - Custos no Setor Público, uma entidade pública deve:','{"A": "priorizar um sistema de acumulação contínuo;", "B": "minimizar número de centros de responsabilidade;", "C": "integrar os relatórios de custos às metas e limites fiscais;", "D": "adotar uma base regular para a geração de informações;", "E": "definir parâmetros para um modelo baseado em atividades."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',45,'Contabilidade Pública',null,'Um tipo de controle importante para os entes públicos refere-se à classificação por fontes ou destinações de recursos (FR), a qual tem como objetivo agrupar receitas que possuam as mesmas normas de aplicação na despesa. Para atingir os objetivos dessa classificação, é necessário observar que:','{"A": "a classificação pode ser adaptada para subsidiar a apuração das metas fiscais;", "B": "a destinação de recursos vinculados a finalidades específicas está restrita ao exercício de sua arrecadação;", "C": "as vinculações podem ser definidas por mandamentos legais ou instrumentos infralegais;", "D": "o controle por fonte ou destinação de recursos é aplicável somente na fase de execução financeira;", "E": "uma FR pode agrupar receitas sujeitas a até duas possibilidades de aplicação."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',46,'Contabilidade Pública',null,'No contexto das entidades públicas, a gestão do caixa e equivalentes de caixa é importante para o melhor aproveitamento dos recursos financeiros que financiam a ação governamental. O MCASP traz algumas disposições para o tratamento do caixa e equivalente de caixa. À luz dessas disposições, considere os ativos a seguir relativos a um ente público municipal, com dados extraídos em 02/01/2022. n Tipo Instituição Vencimento Remuneração Risco Liquidez I CDB Banco Alfa 01/11/2023 110% do CDI Baixo Baixa (no vencimento) II CDB Banco Gama 13/12/2022 103,5% do CDI Baixo Alta (diária) III LCA Banco Beta 30/12/2022 113% do CDI Médio Baixa (no vencimento) IV LCA Banco Gama 23/07/2025 118% do CDI Médio Baixa (no vencimento) V Debêntures Cia. Delta 01/07/2027 IPCA + 7,79% Alto Média VI COE Cia. AA 20/11/2026 Variável Médio Baixa (no vencimento) VII Tesouro Selic 2024 STN 01/04/2024 Selic + 2,3% Baixo Alta VIII Tesouro Prefixado 2026 STN 01/08/2026 13,20% Médio Alta IX Depósitos bancários Banco Ômega -- -- Baixo Alta Os ativos que podem ser considerados como caixa e equivalentes de caixa são:','{"A": "I, II e IV;", "B": "II, IV e IX;", "C": "II, VII e IX;", "D": "III, VII e VIII;", "E": "IV, V e IX. Tipo 1 ̶ Branca – Página 13"}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',47,'Contabilidade Pública',null,'Os estoques de materiais e suprimentos constituem um recurso importante para as entidades públicas que, em grande parte, os emprega na prestação de serviços. Ao tratar da mensuração desses recursos, o MCASP indica como regra geral que deve ser pelo custo histórico ou pelo:','{"A": "custo corrente de reposição, dos dois o maior;", "B": "preço médio ponderado, dos dois o menor;", "C": "preço presumido, conforme política da entidade;", "D": "seu valor justo na data da aquisição;", "E": "valor realizável líquido, dos dois o menor."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',48,'Contabilidade Pública',null,'A gratificação natalina e as férias remuneradas representam ao mesmo tempo um benefício para os servidores e uma obrigação para as entidades públicas. O MCASP os trata como exemplos de obrigações consideradas passivos derivados de apropriações por competência. Ao realizar os registros contábeis patrimoniais relativos a férias remuneradas, um servidor recentemente designado para a função ficou em dúvida quanto ao momento e à abrangência do registro e, após consultar um servidor mais experiente, este lhe esclareceu que:','{"A": "a apropriação das férias deve ser feita mensalmente junto com encargos patronais incidentes;", "B": "a apropriação das férias deve ser feita mensalmente, mas os encargos patronais incidentes, somente no pagamento;", "C": "a apropriação das férias deve ser iniciada apenas quando solicitadas pelo servidor;", "D": "encargos patronais incidentes sobre férias devem ser lançados somente no final do exercício financeiro;", "E": "se um servidor for exonerado durante o exercício financeiro, o valor proporcional de férias apropriado deve ser estornado."}'::jsonb,'A',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',49,'Contabilidade Pública',null,'Uma entidade pública possui um edifício histórico que já foi utilizado como cadeia pública e funciona atualmente como espaço de memória da cidade e também como sede administrativa da Secretaria Municipal de Cultura. Assim, a entidade entende que o imóvel tem potencial de serviços além de seu valor cultural. À luz do Manual de Contabilidade Aplicada ao Setor Público (MCASP), esse imóvel:','{"A": "deve ser registrado separadamente de acordo com os potenciais de uso;", "B": "deve ser reconhecido e mensurado na mesma base de outros ativos imobilizados;", "C": "deve ser tratado contabilmente sob a condição de propriedade para investimento;", "D": "é de difícil mensuração, a qual carece de normatização específica;", "E": "não está sujeito a depreciação em decorrência da sua vida útil indefinida."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',50,'Contabilidade Pública',null,'O Manual de Contabilidade Aplicada ao Setor Público define ativos contingentes como usualmente decorrentes de eventos não planejados ou não esperados que não estejam totalmente sob o controle da entidade e que acarretam a possibilidade de um ingresso de recursos sob a forma de benefícios econômicos ou potencial de serviços. Uma entidade pública acionou judicialmente uma empresa que fraudou informações durante o processo licitatório, pleiteando indenização pelos danos ao erário e à prestação do serviço público. À luz dos procedimentos contábeis patrimoniais descritos no MCASP, a entidade pública deve considerar que:','{"A": "a divulgação em notas explicativas deve ser feita caso se avalie que a probabilidade de êxito é remota;", "B": "como se trata de uma receita possível, o ativo contingente deverá ser reconhecido quando o recurso for arrecadado;", "C": "se a entrada de recursos for considerada provável, o ativo contingente deverá ser registrado em contas de controle;", "D": "uma contingência ativa deverá ser reconhecida se o êxito no processo for considerado possível;", "E": "uma VPA deve ser reconhecida quando o jurídico considerar que há probabilidade de ganho do processo."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',51,'Contabilidade Pública',null,'Três Municípios com limites geográficos comuns firmaram uma parceria para gestão associada (consórcio público) de serviços de diagnóstico por imagem supridos pelos referidos entes, a partir da assinatura de um contrato de rateio em 02/01/20x3. Para a regular condução da parceria, à luz das disposições do MCASP, os entes consorciados devem observar que:','{"A": "o contrato de rateio deve prever somente transferências de recursos financeiros;", "B": "o contrato de rateio deve ser formalizado em cada exercício financeiro;", "C": "o prazo máximo de vigência do contrato de rateio é de dois anos;", "D": "os recursos para cobertura das despesas com transferências ao consórcio público não afetam o orçamento dos entes;", "E": "os serviços prestados pelo consórcio são de acesso exclusivo dos entes consorciados."}'::jsonb,'B',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',52,'Contabilidade Pública',null,'O Plano de Contas Aplicado ao Setor Público (PCASP) padroniza a definição das contas contábeis para três naturezas de informação distintas, cujos registros dão origem ao conjunto das demonstrações contábeis. Além disso, o PCASP aborda lançamentos padronizados em operações típicas realizadas pelas entidades públicas. Pelas regras do PCASP, um lançamento relativo ao reconhecimento por competência de perdas com aplicações financeiras deve:','{"A": "ser registrado somente em contas de controle;", "B": "se processar como informação de natureza patrimonial;", "C": "guardar compatibilidade com ativo e passivo financeiros;", "D": "envolver somente contas da classe 3;", "E": "contemplar todas as naturezas de informação. Tipo 1 ̶ Branca – Página 14"}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',53,'Contabilidade Pública',null,'Ao final do seu primeiro ano de mandato como gestor municipal, um prefeito estava avaliando as demonstrações contábeis para autorizar o seu envio ao tribunal de contas. Como não tinha formação na área de contabilidade, o prefeito chamou o contador geral e o questionou sobre o saldo da dotação constante no Balanço Orçamentário (BO). O contador esclareceu que o saldo da dotação:','{"A": "pode ser transferido para execução no exercício seguinte;", "B": "pode ser utilizado como fonte de recursos para abertura de créditos adicionais;", "C": "decorre de decretos de contingenciamento de despesas ao longo do exercício;", "D": "corresponde a uma economia orçamentária em relação ao que tinha sido previsto;", "E": "indica que não houve arrecadação de receitas suficiente para executar tudo o que foi planejado."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',54,'Contabilidade Pública',null,'Considere as informações do quadro a seguir extraídas do Balanço Financeiro constante da prestação de contas de um ente municipal relativa ao último exercício financeiro. Descrição Valor Transferências Financeiras Concedidas R$ 23.779,00 Pagamentos Extraorçamentários R$ 28.914,00 Recebimentos Extraorçamentários R$ 29.610,00 Transferências Financeiras Recebidas R$ 31.862,00 Saldo em Espécie do Exercício Anterior R$ 146.671,00 Despesa Orçamentária R$ 167.080,00 Saldo em Espécie para o Exercício Seguinte R$ 220.396,00 Receitas Orçamentárias R$ 232.026,00 As informações indicam um resultado financeiro que corresponde a:','{"A": "R$ 8.083,00;", "B": "R$ 64.946,00;", "C": "R$ 73.029,00;", "D": "R$ 73.102,00;", "E": "R$ 73.725,00."}'::jsonb,'E',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',55,'Contabilidade Pública',null,'O conjunto completo das demonstrações contábeis apresenta uma série de informações na estrutura de cada demonstrativo que possibilita análises sobre a posição patrimonial e financeira da entidade, auxiliando os processos de tomada de decisão, de prestação de contas e de responsabilização. No caso em que se deseja avaliar a composição e a evolução do saldo relativo ao uso de bens, serviços e consumo de capital fixo deve-se recorrer à estrutura do(a):','{"A": "balanço patrimonial;", "B": "demonstração das mutações do patrimônio líquido;", "C": "demonstração das variações patrimoniais;", "D": "demonstrativo da receita de alienação de ativos e aplicação dos recursos;", "E": "demonstrativo das receitas de operações de crédito e despesas de capital."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',56,'Contabilidade Geral',null,'O conceito de prudência está presente na Estrutura Conceitual. Nota-se que ativos e receitas não devem estar superavaliados, da mesma forma que passivos e despesas não devem estar subavaliados. Nesse sentido, o conceito se aplica para a situação de maior incerteza para a mensuração de um(a):','{"A": "mercadoria para estoque;", "B": "empréstimo bancário pré-fixado;", "C": "aplicação financeira pré-fixada;", "D": "estimativa de provisão judicial;", "E": "ativo imobilizado."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',57,'Contabilidade Geral',null,'Uma empresa atualizou seu sistema contábil. Após a finalização de implementação do novo sistema, o plano de contas não mais segregava as contas a receber de controladas e coligadas. Nesse caso, a mudança ocorrida afeta a:','{"A": "tempestividade, devido ao atraso na divulgação da informação contábil, prejudicando a sua confiabilidade;", "B": "materialidade, devido à informação ser incompleta e fora dos limites de materialidade e custo;", "C": "consistência, pois a apresentação e a classificação de itens nas demonstrações contábeis devem ser mantidas de um período para outro;", "D": "compensação de valores, pois a entidade deve compensar ativos e passivos ou receitas e despesas para divulgação ao usuário interno;", "E": "uniformidade, pois permite aos usuários identificar e compreender similaridades e diferenças."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',58,'Contabilidade Geral',null,'Uma empresa tem as informações a seguir. Item Valor Depósitos bancários à vista R$ 23.000,00 Aplicações financeiras com maturação no prazo de 30 dias R$ 15.000,00 Investimentos em moedas digitais R$ 10.000,00 Adiantamentos a funcionários R$ 20.000,00 Considerando apenas as informações apresentadas, o saldo contábil de Caixa e Equivalentes de Caixa da empresa é de:','{"A": "R$ 23.000,00;", "B": "R$ 33.000,00;", "C": "R$ 38.000,00;", "D": "R$ 48.000,00;", "E": "R$ 68.000,00. Tipo 1 ̶ Branca – Página 15"}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',59,'Contabilidade Geral',null,'Uma empresa vendeu mercadorias a prazo por R$ 50.000,00 com vencimento para 10 meses. Com base em estimativas passadas, a companhia projeta que 5% dessas vendas não serão cobradas. Dessa forma, o contador deve contabilizar uma:','{"A": "provisão para devedores duvidosos e credora de R$ 2.500,00 no ativo;", "B": "perda estimada de créditos de liquidação duvidosa e credora de R$ 2.500,00 no ativo;", "C": "provisão para devedores duvidosos e devedora de R$ 2.500,00 no ativo;", "D": "perda estimada de créditos de liquidação duvidosa e devedora de R$ 2.500,00 no ativo;", "E": "provisão para devedores duvidosos e devedora de R$ 5.000,00 no resultado."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',60,'Contabilidade Geral',null,'Uma empresa comercial realizou as seguintes operações em seus estoques na compra de pares de tênis: - Em 15/03 comprou um lote de 20 pares por R$ 600,00 cada; - Em 17/03 comprou um lote de 20 pares por R$ 700,00 cada; e - Em 20/03 vendeu 20 pares por R$ 1.000,00 cada. Considerando-se as informações apresentadas e segundo o critério de valoração de estoques:','{"A": "o critério do UEPS (Último a Entrar, Primeiro a Sair) resulta no maior lucro bruto;", "B": "o critério do UEPS (Último a Entrar, Primeiro a Sair) resulta em um lucro bruto de R$ 750,00 maior que o custo médio ponderado;", "C": "o critério do PEPS (Primeiro a Entrar, Primeiro a Sair) resulta no menor lucro bruto;", "D": "o critério do custo médio ponderado resulta no maior lucro bruto;", "E": "o critério do PEPS (Primeiro a Entrar, Primeiro a Sair) resulta em um lucro bruto de R$ 1.500,00 maior que o UEPS (Último a Entrar, Primeiro a Sair)."}'::jsonb,'X',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','questão ANULADA pela banca; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',61,'Contabilidade Geral',null,'Uma empresa adquiriu à vista, em 01/01/2023, um seguro no valor de R$ 9.000,00 para o prédio administrativo. O referido seguro tem vigência entre 01/01/2023 e 31/12/2023. Nesse caso, o contador deve contabilizar os lançamentos de reconhecimento inicial e de apropriação da despesa pelo regime de competência, respectivamente:','{"A": "Débito – Caixa/Bancos (Ativo Circulante) R$ 9.000,00 Crédito – Seguros Antecipados (Ativo Circulante) R$ 9.000,00 e Débito – Despesas com Seguros (Ativo Circulante) R$ 750,00 Crédito – Seguros Antecipados (Ativo Circulante) R$ 750,00;", "B": "Débito – Despesas com Seguros (Despesa) R$ 9.000,00 Crédito – Seguros Antecipados (Ativo Circulante) R$ 9.000,00 e Débito – Seguros Antecipados (Ativo Circulante) R$ 750,00 Crédito – Caixa/Bancos (Ativo Circulante) R$ 750,00;", "C": "Débito – Seguros Antecipados (Ativo Circulante) R$ 9.000,00 Crédito – Caixa/Bancos (Ativo Não Circulante) R$ 9.000,00 e Débito – Despesas com Seguros (Passivo) R$ 750,00 Crédito – Seguros Antecipados (Ativo Não Circulante) R$ 750,00;", "D": "Débito – Seguros Antecipados (Ativo Circulante) R$ 9.000,00 Crédito – Caixa/Bancos (Ativo Circulante) R$ 9.000,00 e Débito – Despesas com Seguros (Despesa) R$ 750,00 Crédito – Seguros Antecipados (Ativo Circulante) R$ 750,00;", "E": "Débito – Seguros Antecipados (Ativo Circulante) R$ 8.250,00 Crédito – Caixa/Bancos (Ativo Circulante) R$ 8.250,00 e Débito – Despesas com Seguros (Despesa) R$ 750,00 Crédito – Seguros Antecipados (Ativo Circulante) R$ 750,00. Tipo 1 ̶ Branca – Página 16"}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',62,'Contabilidade Geral',null,'Uma empresa comercial vendeu um produto pelo valor prefixado de R$ 28.000,00 para ser recebido daqui a 14 meses. A taxa de juros da operação, conhecida, era de 1,924% ao mês. Montante Juros exercício Amortização Parcela 28.000,00 538,72 1.461,28 2.000,00 26.000,00 500,24 1.499,76 2.000,00 24.000,00 461,76 1.538,24 2.000,00 22.000,00 423,28 1.576,72 2.000,00 20.000,00 384,80 1.615,20 2.000,00 18.000,00 346,32 1.653,68 2.000,00 16.000,00 307,84 1.692,16 2.000,00 14.000,00 269,36 1.730,64 2.000,00 12.000,00 230,88 1.769,12 2.000,00 10.000,00 192,40 1.807,60 2.000,00 8.000,00 153,92 1.846,08 2.000,00 6.000,00 115,44 1.884,56 2.000,00 4.000,00 76,96 1.923,04 2.000,00 2.000,00 38,48 1.961,52 2.000,00 Considerando as informações apresentadas, o contador deve registrar os seguintes lançamentos:','{"A": "Débito – Clientes (Ativo Não Circulante) R$ 28.000,00 Crédito – Ajuste a valor presente (Ativo Não Circulante) R$ 4.040,40 Crédito – Receita Líquida com vendas (Demonstração do Resultado do Exercício) R$ 23.959,60;", "B": "Débito – Clientes (Ativo Não Circulante) R$ 28.000,00 Débito – Ajuste a valor presente (Demonstração do Resultado do Exercício) R$ 4.040,40 Crédito – Receitas com vendas (Demonstração do Resultado do Exercício) R$ 23.959,60;", "C": "Débito – Clientes (Ativo Circulante) R$ 28.000,00 Crédito – Ajuste a valor presente (Ativo Circulante) R$ 4.040,40 Crédito – Receita Líquida com vendas (Demonstração do Resultado do Exercício) R$ 23.959,60;", "D": "Débito – Clientes (Ativo Não Circulante) R$ 23.959,60 Débito – Ajuste a valor presente (Demonstração do Resultado do Exercício) R$ 4.040,40 Crédito – Receitas com vendas (Demonstração do Resultado do Exercício) R$ 28.000,00;", "E": "Débito – Clientes (Ativo Não Circulante) R$ 28.000,00 Crédito – Receita Líquida com vendas (Demonstração do Resultado do Exercício) R$ 28.000,00."}'::jsonb,'A',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',63,'Contabilidade Geral',null,'Ativos e passivos que podem ser avaliados a valor justo na mensuração após reconhecimento são:','{"A": "softwares, mercadorias para revenda e ações;", "B": "mercadorias para revenda, provisões e ações;", "C": "investimentos em coligada, mercadorias para revenda e provisões;", "D": "edifícios, derivativos e debêntures;", "E": "provisões, softwares e derivativos."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',64,'Contabilidade Geral',null,'A empresa XYZ (investidora) tem um investimento na empresa FGH (investida). Em 31 de dezembro de X1, o patrimônio líquido da investida é de R$ 100.000,00 e a investidora possui 40% de participação na FGH (sua coligada). Durante o ano de X1, a investida vendeu um terreno para a investidora e lucrou R$ 20.000,00 nessa operação. Considerando-se as informações apresentadas, a aplicação do método de equivalência patrimonial em 31 de dezembro de X1 resulta em um valor de:','{"A": "R$ 20.000,00;", "B": "R$ 32.000,00;", "C": "R$ 40.000,00;", "D": "R$ 80.000,00;", "E": "R$ 100.000,00."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',65,'Contabilidade Geral',null,'Por vezes é difícil avaliar se um ativo intangível gerado internamente se qualifica para o reconhecimento, devido às diversas dificuldades. Para avaliar se um ativo intangível gerado internamente atende aos critérios de reconhecimento, a entidade deve classificar a geração do ativo na fase de pesquisa e na fase de desenvolvimento. Segundo CPC 04, um exemplo da fase de pesquisa é:','{"A": "avaliação de alternativas para possíveis materiais do produto;", "B": "realização de estudos de viabilidade;", "C": "testes do protótipo;", "D": "projeto, construção e operação de fábrica-piloto;", "E": "construção de modelos pré-produção. Tipo 1 ̶ Branca – Página 17"}'::jsonb,'A',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',66,'Contabilidade Geral',null,'Uma empresa adquiriu a prazo mercadorias para a revenda por R$ 2.250,00 para pagar em 3 meses (taxa de juros efetiva de 14,47% ao mês ou 50% total do período e considerada material para a empresa). Em seguida, a empresa e o fornecedor realizaram um acordo com uma instituição financeira – operação de forfait, também chamada de risco sacado. Considerando as informações apresentadas, as contabilizações iniciais e subsequentes são:','{"A": "Início Débito – Estoques (Ativo Circulante) R$ 1.500,00 Crédito – Fornecedores (Passivo Circulante) R$ 1.500,00 Subsequentes Débito – Fornecedores (Passivo Circulante) R$ 1.500,00 Crédito – Empréstimos (Passivo Circulante) R$ 1.500,00 Após 3 meses Débito – Despesa de juros (DRE) R$ 750,00 Crédito – Empréstimos (Passivo Circulante) R$ 750,00;", "B": "Início Débito – Estoques (Ativo Circulante) R$ 2.250,00 Crédito – Fornecedores (Passivo Circulante) R$ 2.250,00 Após 3 meses Débito – Despesa de juros (DRE) R$ 1.125,00 Crédito – Fornecedores (Passivo Circulante) R$ 1.125,00;", "C": "Início Débito – Estoques (Ativo Circulante) R$ 2.250,00 Crédito – Fornecedores (Passivo Circulante) R$ 2.250,00 Subsequentes Débito – Fornecedores (Passivo Circulante) R$ 2.250,00 Crédito – Empréstimos (Passivo Circulante) R$ 2.250,00 Após 3 meses Débito – Despesa de juros (DRE) R$ 750,00 Crédito – Empréstimos (Passivo Circulante) R$ 750,00;", "D": "Início Débito – Estoques (Ativo Circulante) R$ 1.500,00 Crédito – Fornecedores (Passivo Circulante) R$ 1.500,00 Após 3 meses Débito – Despesa de juros (DRE) R$ 750,00 Crédito – Fornecedores (Passivo Circulante) R$ 750,00;", "E": "Início Débito – Estoques (Ativo Circulante) R$ 2.250,00 Crédito – Empréstimos (Passivo Circulante) R$ 2.250,00 Após 3 meses Débito – Despesa de juros (DRE) R$ 750,00 Crédito – Empréstimos (Passivo Circulante) R$ 750,00."}'::jsonb,'A',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',67,'Contabilidade Geral',null,'Uma empresa foi processada por três supostas violações: (a) uso não autorizado de uma marca registrada e a reivindicação é de R$ 100 milhões; (b) não pagamento de uma gratificação a 2.000 empregados que foram demitidos, no montante de R$ 50 milhões; e (c) prejuízos ambientais causados pela deposição de resíduos no rio próximo à fábrica em que ambientalistas estão reivindicando danos e custos de despoluição do rio. Os advogados da empresa acreditam que nem todos os casos têm a mesma chance de ocorrerem e comunicou à empresa a seguinte avaliação: Ação 1: As chances desse processo são remotas. Ação 2: É provável que a empresa tenha que pagar os empregados demitidos, mas a melhor estimativa do montante seria de R$ 30 milhões. Ação 3: Não há nenhuma lei que obrigue uma entidade a pagar por tais danos, somente políticas ambientais da empresa e propagandas nas mídias (obrigação não formalizada), contudo, o valor dos danos não pode ser estimado com confiabilidade. Considerando as informações apresentadas, a empresa deve:','{"A": "divulgar em notas explicativas todas as ações, sem a necessidade de provisionamento de valores;", "B": "provisionar a ação 2 no valor de R$ 50 milhões e divulgar em nota explicativa a ação 3;", "C": "provisionar a ação 2 no valor de R$ 50 milhões, sem a necessidade de divulgação em notas explicativas das ações 1 e 3;", "D": "provisionar a ação 2 no valor de R$ 30 milhões, divulgar em nota explicativa a ação 3 e para a ação 1 nenhuma divulgação é exigida;", "E": "provisionar as ações 1 e 2 no valor de R$ 100 milhões e R$ 50 milhões, respectivamente, e para a ação 3 nenhuma divulgação é exigida."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',68,'Contabilidade Geral',null,'Uma empresa possui ações ao valor nominal de R$ 1,00 cada e decidiu realizar um aumento de capital no montante de 50.000 ações ao preço de R$ 1,30 cada. Considerando as informações apresentadas, o contador deve registrar os seguintes lançamentos:','{"A": "Débito – Caixa (Ativo Circulante) R$ 65.000,00 Crédito – Ágio na Emissão de Ações (Capital Social) R$ 65.000,00;", "B": "Débito – Caixa (Ativo Circulante) R$ 65.000,00 Crédito – Capital Social (Patrimônio Líquido) R$ 50.000,00 Crédito – Receitas (Demonstração do Resultado do Exercício) R$ 15.000,00;", "C": "Débito – Investimentos (Ativo Não Circulante) R$ 65.000,00 Crédito – Capital Social (Patrimônio Líquido) R$ 65.000,00;", "D": "Débito – Caixa (Ativo Circulante) R$ 15.000,00 Crédito – Receitas (Demonstração do Resultado do Exercício) R$ 15.000,00;", "E": "Débito – Caixa (Ativo Circulante) R$ 65.000,00 Crédito – Capital Social (Patrimônio Líquido) R$ 50.000,00 Crédito – Ágio na Emissão de Ações (Reserva de Capital) R$ 15.000,00. Tipo 1 ̶ Branca – Página 18"}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',69,'Contabilidade Geral',null,'Uma empresa do segmento de shopping center possui seus empreendimentos classificados como propriedades para investimento mensuradas a custo. Devido a uma mudança na estratégia da empresa, mais inclinada para a venda dessas propriedades para investimento, ela decide mensurar seus empreendimentos ao valor justo. Nesse caso, o fato caracteriza um(a):','{"A": "mudança na estimativa contábil;", "B": "erro de período anterior;", "C": "mudança na política contábil;", "D": "efeito na conversão das demonstrações financeiras;", "E": "necessidade de impairment dos empreendimentos."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',70,'Contabilidade Geral',null,'O conceito de controle está relacionado ao investidor controlar a investida quando está exposto a, ou tem direitos sobre, retornos variáveis decorrentes de seu envolvimento com a investida e tem a capacidade de afetar esses retornos por meio de seu poder sobre a investida. Um exemplo de direito que pode dar poder ao investidor é ter:','{"A": "as operações entre o investidor e a investida;", "B": "o direito de nomear membros do pessoal-chave da alta administração da investida;", "C": "a escolha de intercâmbio de gerentes;", "D": "o fornecimento de informação técnica;", "E": "o direito de participação nos processos de elaboração de memorandos."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',71,'Administração Financeira e Orçamentária',null,'Durante um treinamento sobre os princípios e normas que regem o processo orçamentário dos entes públicos, um dos alunos apresentou um questionamento acerca da abrangência do orçamento anual. Segundo ele, se há um balanço do setor público nacional que inclui todos os entes anualmente, deveria haver também um orçamento geral que englobasse os orçamentos de todos os entes federativos. Porém, esse raciocínio do aluno em treinamento não tem base nos princípios orçamentários, e pode ser refutado pelo princípio do(a):','{"A": "anualidade;", "B": "exclusividade;", "C": "não vinculação;", "D": "orçamento bruto;", "E": "unidade."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',72,'Administração Financeira e Orçamentária',null,'Dos três instrumentos de planejamento e orçamento governamental previstos na Constituição da República de 1988, o PPA é o que tem menor regulamentação e detalhamento do seu conteúdo e processo de elaboração. A despeito dessa reduzida regulamentação, uma exigência consolidada acerca do PPA é a:','{"A": "discussão com a sociedade em audiências públicas;", "B": "inclusão dos programas sujeitos à aplicação mínima de recursos;", "C": "integração prévia com as metas fiscais estabelecidas na LDO;", "D": "necessidade de apreciação pelo tribunal de contas;", "E": "vinculação com o programa de governo do gestor em exercício."}'::jsonb,'A',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',73,'Administração Financeira e Orçamentária',null,'Um ente público municipal publicou um dos seus instrumentos de planejamento que continha o seguinte trecho: “Em atendimento às disposições do Art. 4º, I, e), da Lei Complementar nº 101, de 4 de maio de 2000, esta lei estabelece que todas as secretarias municipais enviarão informações em periodicidade quadrimestral, conforme padrão definido pela CGM para apuração, controle e acompanhamento dos custos dos serviços prestados pelo método de custeio padrão”. Além dessa disposição, esse instrumento:','{"A": "apresenta detalhes sobre o orçamento de investimento das empresas públicas municipais;", "B": "define condições e exigências para transferências de recursos a entidades públicas e privadas;", "C": "dispõe também sobre diretrizes e objetivos relativos aos programas de duração continuada;", "D": "estabelece normas de gestão financeira e patrimonial da administração pública municipal;", "E": "fornece as bases para a elaboração do Relatório Resumido da Execução Orçamentária."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',74,'Administração Financeira e Orçamentária',null,'O planejamento é uma atividade importante para possibilitar a execução de políticas públicas bem formuladas que geram benefícios a toda a sociedade. Por isso, a Constituição da República de 1988 prevê instrumentos que formalizam esse processo para todas as esferas governamentais. O instrumento que estima a receita e fixa a despesa de um ente para um determinado exercício também:','{"A": "deve apresentar a despesa fixada por poder e órgãos, que em geral reflete a estrutura administrativa do ente;", "B": "deve instituir fundos para a cobertura de despesas extraordinárias;", "C": "deve vincular a aplicação de receitas de capital em investimentos em atividades finalísticas;", "D": "pode autorizar a concessão de garantias a órgãos e entidades da sua estrutura;", "E": "pode autorizar percentual da despesa fixada para a abertura de créditos adicionais especiais. Tipo 1 ̶ Branca – Página 19"}'::jsonb,'A',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',75,'Administração Financeira e Orçamentária',null,'Durante um exercício financeiro em um ente municipal, foi detectada a necessidade de reforçar dotações que se mostraram insuficientes e também abrir novos créditos para fazer frente a despesas não previstas, conforme descrito a seguir. Descrição Data da abertura Valor Fonte de recursos Crédito suplementar 1 28/mai R$ 5.000,00 Superávit financeiro Crédito suplementar 2 20/nov R$ 13.000,00 Excesso de arrecadação Crédito especial 1 05/mai R$ 7.000,00 Anulação parcial de dotações Crédito especial 2 23/jul R$ 23.000,00 Operações de crédito Crédito especial 3 02/set R$ 15.000,00 Reserva de contingência A partir desses dados e das disposições normativas sobre créditos adicionais, a dotação inicial prevista na LOA foi acrescida em:','{"A": "R$ 18.000,00;", "B": "R$ 41.000,00;", "C": "R$ 45.000,00;", "D": "R$ 56.000,00;", "E": "R$ 63.000,00."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',76,'Administração Financeira e Orçamentária',null,'Sob a perspectiva da receita, o orçamento deve, a partir do preceito da universalidade, prever o fluxo de ingressos com o qual o ente poderá contar ao longo de um exercício financeiro. A despeito disso, há ingressos de recursos que não compõem a receita pública e, portanto, não podem custear as ações orçamentárias, como é o caso de:','{"A": "multas e juros de mora de tributos vencidos;", "B": "receitas de depósitos em garantia;", "C": "receitas de permissão de uso;", "D": "rendimentos de aplicações financeiras;", "E": "taxa de licenciamento de projetos sociais."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',77,'Administração Financeira e Orçamentária',null,'Tanto a receita como a despesa pública são processadas em etapas visando subsidiar o processo de controle e prestação de contas. Sob a perspectiva da receita, a sua previsão é uma etapa concretizada na Lei Orçamentária Anual (LOA) que:','{"A": "independe das metas e limites fiscais definidos para cada exercício;", "B": "deve adotar metodologia uniforme para todas as categorias de receitas;", "C": "resulta da estimativa das necessidades de financiamento do governo;", "D": "antecede a fixação do montante de despesas incluídas na lei do orçamento;", "E": "não deve impactar a potencial abertura de créditos adicionais autorizados na LOA."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',78,'Administração Financeira e Orçamentária',null,'Uma das classificações legais da despesa pública refere-se à classificação funcional, a qual segrega as dotações orçamentárias em funções e subfunções, buscando responder basicamente à indagação “em que área” de ação governamental a despesa será realizada. Nesse contexto, considerando que se enquadre na função Administração, as despesas gerais da Controladoria Geral de um Município poderiam ser congregadas na subfunção relativa a:','{"A": "administração de receitas;", "B": "controle administrativo;", "C": "controle externo;", "D": "controle interno;", "E": "defesa do interesse público."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',79,'Administração Financeira e Orçamentária',null,'Um termo de colaboração entre a Controladoria Geral de um Município e o respectivo tribunal de contas envolveu a transferência de recursos para a execução de algumas despesas, conforme as regras aplicáveis às descentralizações de crédito. Por tratar-se de uma descentralização, a operação:','{"A": "deve assegurar que as dotações sejam empregadas integralmente na consecução do objetivo do programa;", "B": "deve ser especificada quando da fixação da despesa;", "C": "está sujeita a regras especiais para empenho das dotações;", "D": "pode ser enquadrada como transferência ou como transposição;", "E": "somente pode ser registrada após a publicação da programação financeira."}'::jsonb,'A',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',80,'Administração Financeira e Orçamentária',null,'A Lei nº 4.320, de 17 de março de 1964, dispõe sobre normas que subsidiam a elaboração e controle dos orçamentos e balanços dos entes públicos. Quanto à apresentação da Lei do Orçamento, a Lei nº 4.320/1964 determina que será acompanhada de:','{"A": "critérios para elaboração da programação financeira e cronograma de desembolso do exercício;", "B": "quadro demonstrativo da compatibilidade entre as metas fiscais e receitas previstas;", "C": "quadro demonstrativo do programa anual de trabalho do governo;", "D": "rol de dotações orçamentárias sujeitas à descentralização de créditos;", "E": "rol de responsáveis pela execução do orçamento conforme a estrutura administrativa do ente. Tipo 1 ̶ Branca – Página 20"}'::jsonb,'C',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',81,'Administração Financeira e Orçamentária',null,'Os critérios e limites para controle da despesa total com pessoal são tratados na Lei de Responsabilidade Fiscal. De acordo com a referida lei complementar, dada a relevância da despesa com pessoal na composição dos gastos públicos, a verificação do cumprimento dos limites desse tipo de despesa:','{"A": "cabe ao Poder Legislativo a partir das prestações de contas anuais;", "B": "é apresentada no Relatório Resumido de Execução Orçamentária;", "C": "é prerrogativa exclusiva das instâncias de controle interno;", "D": "inclui-se entre as competências da Secretaria do Tesouro Nacional;", "E": "será realizada ao longo do exercício financeiro, ao final de cada quadrimestre."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',82,'Administração Financeira e Orçamentária',null,'Ao elaborar o projeto de Lei de Diretrizes Orçamentárias (LDO) para um exercício que correspondia ao primeiro ano de mandato, a recém-formada equipe de planejamento de um dado Município precisa atentar para um dispositivo constitucional, o qual dispõe que o referido ente deve:','{"A": "adotar, proporcionalmente à sua receita, as metas fiscais definidas no âmbito federal;", "B": "conduzir sua política fiscal de forma a manter a dívida pública em níveis sustentáveis;", "C": "definir um percentual limite da sua receita corrente líquida que pode ser comprometido com endividamento;", "D": "observar as diretrizes fiscais estabelecidas pelo respectivo Estado;", "E": "submeter o projeto à apreciação do respectivo tribunal de contas."}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',83,'Administração Financeira e Orçamentária',null,'Devido à sua posição geográfica, em uma área montanhosa de um determinado Município, é recorrente a ocorrência de inundações e deslizamentos associados às chuvas sazonais de verão. Como esses eventos demandam a intervenção do poder público municipal, o Manual de Demonstrativos Fiscais recomenda que:','{"A": "a intervenção do poder público frente a essa situação emergencial seja custeada com créditos especiais;", "B": "a reserva de contingência deva ser direcionada para a cobertura de despesas necessárias para sanar a situação emergencial;", "C": "as despesas com ações para mitigar tais efeitos devam ser previstas na LDO e na LOA;", "D": "as providências a serem tomadas pelo poder público sejam previstas no anexo de riscos fiscais;", "E": "o ente publique decreto de calamidade pública para suspender as restrições fiscais até o fim da emergência."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',84,'Administração Financeira e Orçamentária',null,'O Relatório Resumido da Execução Orçamentária (RREO) tem como objetivo subsidiar o acompanhamento e controle das receitas e despesas previstas no orçamento, conforme legalmente definido. Ao ser questionado sobre os limites que podem ser acompanhados no RREO, um servidor da área de contabilidade exemplificou citando o limite relativo a:','{"A": "aplicação de recursos em consórcios públicos;", "B": "concessão de garantias e contragarantias a entes públicos;", "C": "despesas decorrentes das parcerias público-privadas;", "D": "destinação de recursos orçamentários ao serviço da dívida;", "E": "inscrição de despesas em restos a pagar não processados."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',85,'Administração Financeira e Orçamentária',null,'Um servidor foi designado para assessorar a comissão permanente de orçamentos de uma câmara municipal, formada, em sua maioria, por novos vereadores. O servidor preparou uma apresentação com regras constitucionais sobre apresentação e aprovação de emendas ao projeto de lei orçamentária. Entre as orientações contidas na apresentação do servidor, destaca-se a necessidade de:','{"A": "aprovação com maioria qualificada dos membros do Poder Legislativo;", "B": "independência em relação às disposições de orçamentos anteriores;", "C": "indicação de fonte de recursos para proposição de emendas;", "D": "que as emendas não estejam relacionadas a erros e incorreções da proposta orçamentária;", "E": "se referir a novas despesas, não iniciadas em exercícios anteriores."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',86,'Auditoria',null,'Entre os objetivos de uma auditoria financeira encontram-se elementos que são reconhecidos, mensurados e apresentados em demonstrações financeiras. Em decorrência disso, as auditorias financeiras devem ser realizadas:','{"A": "a partir de escopo definido pela entidade auditada;", "B": "com garantia de asseguração limitada;", "C": "como trabalhos de certificação;", "D": "para a emissão de relatório direto;", "E": "somente em demonstrações de encerramento do exercício."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',87,'Auditoria',null,'Um órgão de controle recebeu uma representação, com fundamentação razoável, envolvendo empresas fornecedoras de merenda escolar para a rede escolar de um Município, que sugere a ocorrência de formação de cartel e superfaturamento. O órgão entendeu ser pertinente iniciar uma ação de fiscalização e designou uma comissão com três servidores com a formalização de um requerimento de:','{"A": "auditoria;", "B": "inspeção;", "C": "levantamento;", "D": "monitoramento;", "E": "acompanhamento. Tipo 1 ̶ Branca – Página 21"}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',88,'Auditoria',null,'No contexto das auditorias realizadas nas entidades públicas, a partir dos princípios fundamentais de auditoria do setor público, um estágio importante do processo de auditoria refere-se à definição do escopo, ou seja, do conjunto de recortes de objeto que serão analisados e os critérios que serão utilizados para responder a cada questão do trabalho. A definição desse estágio:','{"A": "configura uma etapa operacional do planejamento;", "B": "é prerrogativa específica da entidade auditada;", "C": "está sujeita à redução em se tratando de asseguração limitada;", "D": "não está sujeita a alterações durante o trabalho de auditoria;", "E": "representa um elemento estratégico do planejamento do auditor."}'::jsonb,'E',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',89,'Auditoria',null,'Os auditores reconhecem que a materialidade é um quesito relevante nos trabalhos de auditorias, porém, sua avaliação envolve julgamento profissional e, portanto, subjetividade. Quanto a esse quesito, à luz dos princípios fundamentais de auditoria do setor público, é correto afirmar que:','{"A": "a materialidade de uma questão independe do contexto em que ela ocorre;", "B": "a análise da materialidade afeta as decisões relativas à natureza e à extensão dos procedimentos de auditoria, mas não afeta a avaliação dos seus resultados;", "C": "a consideração de aspectos qualitativos deve ser evitada em termos de julgamento de materialidade;", "D": "as necessidades dos usuários não devem afetar a determinação da materialidade feita pelo auditor;", "E": "o julgamento da materialidade pode se relacionar a um item individual ou a um grupo de itens, tomados em conjunto."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',90,'Auditoria',null,'No planejamento e condução dos trabalhos de auditoria, os auditores devem gerenciar os riscos de fornecer um relatório que seja inadequado nas circunstâncias da auditoria. Acerca desse processo de gerenciamento dos riscos em auditoria, analise os itens a seguir. I. As limitações inerentes a todas as auditorias significam que uma auditoria nunca pode fornecer absoluta certeza da condição objeto. II. Com um risco aceitável maior, a asseguração limitada perde significância para os usuários da auditoria. III. O fornecimento de um nível de asseguração razoável aumenta a necessidade de redução do risco de auditoria. Está correto somente o que se afirma em:','{"A": "I;", "B": "II;", "C": "I e II;", "D": "I e III;", "E": "II e III."}'::jsonb,'D',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',91,'Auditoria',null,'Uma parte de extrema relevância nos trabalhos do auditor se refere à documentação de auditoria (os chamados papéis de trabalho), que consiste em documentos que suportam o trabalho de auditoria. À luz da relevância de tais documentos para o alcance dos objetivos dos trabalhos de auditoria, um auditor deve observar que:','{"A": "a elaboração dos papéis de trabalho é de responsabilidade exclusiva do auditor;", "B": "o início da elaboração dos papéis de trabalho deve se dar a partir da conclusão do planejamento da auditoria;", "C": "os papéis de trabalho correntes têm relação direta com o período e com o objeto dos exames;", "D": "os papéis de trabalho devem ser mantidos até o encerramento dos trabalhos de auditoria do exercício seguinte;", "E": "os papéis de trabalho não devem ser usados em mais de um trabalho de auditoria."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',92,'Auditoria',null,'Ao iniciar um trabalho de auditoria, um auditor executou os testes de controle que planejara, mas por precaução e atendimento às recomendações normativas, decidiu aplicar a técnica da indagação e realizar procedimentos adicionais para obter evidência de auditoria sobre a efetividade operacional dos controles. De acordo com as normas de auditoria, esses procedimentos adicionais:','{"A": "desconsideram os meios pelos quais os controles foram aplicados;", "B": "devem certificar se houve concordância da alta administração;", "C": "devem considerar a consistência com que os controles foram aplicados ao longo do período;", "D": "devem ser aprovados previamente pelo comitê de auditoria interna;", "E": "são eficazes apenas na fase inicial dos trabalhos de auditoria."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',93,'Auditoria',null,'Em análises estatísticas, somente as amostragens probabilísticas permitem a correta generalização para a população dos resultados amostrais. Um tipo de amostragem que pode cumprir esse objetivo é a amostragem aleatória simples. Ao definir pela aplicação desse tipo de amostragem, um auditor deve considerar que:','{"A": "a amostra gerada tende a apresentar uma distribuição normal;", "B": "a seleção de um elemento não interfere na seleção dos demais;", "C": "é necessário garantir que todos os estratos da população sejam representados nos elementos amostrais;", "D": "os grupos formados devem ser exaustivos e mutuamente excludentes;", "E": "recomenda-se aplicá-la unicamente em populações finitas. Tipo 1 ̶ Branca – Página 22"}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',94,'Auditoria',null,'Um jovem auditor designado para substituir um colega em uma equipe de auditoria foi requisitado a aplicar uma técnica de auditoria que gerasse evidências sobre a efetividade dos controles e a segregação de funções durante a execução de um processo de recebimentos e registro de matérias-primas em um parque fabril. Após analisar os papéis de trabalho, o auditor responsável questionou o jovem auditor por ter recorrido a registros documentais fornecidos pela empresa em vez de realizar uma:','{"A": "confirmação externa;", "B": "extração eletrônica de dados;", "C": "indagação escrita;", "D": "inspeção direta;", "E": "observação direta."}'::jsonb,'E',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',95,'Auditoria',null,'Uma equipe de auditores de um órgão de controle recebeu um relatório sobre o pagamento de vagas em creches privadas para atendimento de crianças até 5 anos de idade, para as quais foi informado que não havia vagas nas creches municipais, na região onde as respectivas famílias residiam. Os auditores resolveram pedir um relatório sobre a ocupação de vagas nas creches da referida região, com o objetivo de constatar se não havia ociosidade e confirmar a pertinência do gasto. A análise dos relatórios de gastos e das planilhas com informações sobre capacidade e nível de ocupação das creches está alinhada com a técnica de:','{"A": "circularização;", "B": "revisão analítica;", "C": "análise de contas;", "D": "mapa de processo;", "E": "conferência de cálculos."}'::jsonb,'B',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',96,'Auditoria',null,'A matriz de achados é um papel de trabalho utilizado para estruturar o desenvolvimento dos achados de uma auditoria, conforme a ilustração a seguir. Descrição do achado Situação encontrada Objeto Critério Evidência Causa Efeito Encaminhamento Achado 1 Achado 2 Achado n Após concluir a aplicação dos procedimentos planejados, em consulta a outros papéis de trabalho, o auditor encontrou a seguinte anotação: “Registrar na matriz de achados: prejuízo ao erário pelo pagamento de vantagem remuneratória a servidores motivada por acúmulo indevido de funções”. Considerando os atributos elementares da matriz de achados, essa anotação deveria ser inserida na coluna relativa a:','{"A": "causa;", "B": "efeito;", "C": "evidência;", "D": "objeto;", "E": "situação encontrada."}'::jsonb,'B',true,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',97,'Auditoria',null,'Após finalizar os procedimentos planejados, revisar e analisar os papéis de trabalho e a matriz de achados de auditoria de um trabalho de auditoria financeira para o qual fora contratado, um auditor concluiu que as demonstrações contábeis apresentavam distorções relevantes. Além disso, no julgamento do auditor, os efeitos dessas distorções sobre as demonstrações contábeis eram relevantes e generalizados. De acordo com as normas de auditoria, diante dessa situação, o auditor:','{"A": "deve emitir uma opinião adversa;", "B": "pode se abster de emitir opinião;", "C": "deve emitir uma opinião com ressalva;", "D": "pode emitir uma opinião não modificada;", "E": "deve enfatizar sua conclusão nos principais assuntos de auditoria."}'::jsonb,'A',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',98,'Auditoria',null,'No contexto da auditoria governamental, o monitoramento consiste na adoção de ações pela unidade de auditoria, com o objetivo de verificar se as medidas implementadas pela unidade auditada estão de acordo com as recomendações emitidas, bem como se foram suficientes para solucionar a situação apontada como inadequada frente aos critérios adotados. Nesse processo de monitoramento, a etapa inicial consiste no(a):','{"A": "recebimento e avaliação de respostas da unidade auditada;", "B": "realização de testes e diligências adicionais julgados necessários;", "C": "estabelecimento de prazo para o envio de resposta pela unidade auditada;", "D": "comunicação à unidade auditada das conclusões obtidas pela unidade de auditoria;", "E": "estabelecimento de um processo de comunicação acerca da implementação das recomendações à administração da unidade auditada."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',99,'Auditoria',null,'Uma equipe de auditoria interna foi requerida a realizar um exame com o propósito de fornecer para a organização uma avaliação independente sobre os processos de governança conduzidos pela organização. De acordo com as Normas dos Profissionais de Auditoria Interna, esse trabalho deve ser conduzido sob a perspectiva de um:','{"A": "relatório direto de conformidade;", "B": "serviço de avaliação (assurance);", "C": "serviço de consultoria;", "D": "trabalho de auditoria de gestão;", "E": "trabalho de certificação. Tipo 1 ̶ Branca – Página 23"}'::jsonb,'B',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria Geral do Município do Rio de Janeiro','Contador',2023,null,'Tipo 1',100,'Auditoria',null,'De acordo com as Normas dos Profissionais de Auditoria Interna, sob a perspectiva da independência organizacional, o executivo chefe de auditoria deve reportar-se a um nível dentro da organização que permita à atividade de auditoria interna cumprir suas responsabilidades. Os itens a seguir são exemplos de reporte funcional entre o executivo chefe de auditoria e o conselho, que são indicativos dessa independência, EXCETO:','{"A": "aprovação do planejamento de auditoria baseado em riscos;", "B": "aprovação de decisões referentes à nomeação e demissão do executivo chefe de auditoria;", "C": "comunicações acerca de alterações na estrutura de controles e gerenciamento de riscos;", "D": "comunicações sobre o desempenho do plano de auditoria interna;", "E": "questionamentos acerca da existência de escopos inadequados ou limitações de recursos."}'::jsonb,'C',false,false,'RJ','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/contadorcgm-cont-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-cgm-gabarito-definitivo.pdf','disciplina atribuída pela ordem do caderno')
